$teamLink=fn(string $destination,array $params=[])=>'?'.http_build_query(['page'=>$destination]+$params);
$teamHeaders=['Date','Shift','Status','Check in','Check out','Worked','Late','Overtime'];
?>
<link rel="stylesheet" href="assets/team-workspace.css?v=<?=filemtime(dirname(__DIR__,2).'/assets/team-workspace.css')?>">
<div class="team-workspace <?=h($page)?>">
 <?php if(!$teamSelected):?>
 <section class="panel team-records"><div class="team-heading"><div><h3><?=$page==='team_people'?'Team members':'Current attendance'?></h3><p><?=count($teamMembers)?> <?=count($teamMembers)===1?'employee':'employees'?> shown<?php if($page==='team_attendance'):?> · Updated <?=h(date('d M, h:i A'))?> · <?=h(date_default_timezone_get())?><?php endif;?></p></div><?php if($teamSearch!==''):?><a class="wide-button" href="<?=h($teamLink($page))?>">Show all team members</a><?php endif;if($page==='team_attendance'):?><a class="wide-button" href="<?=h($teamLink($page,['search'=>$teamSearch]))?>">Refresh attendance</a><?php endif;?></div>
 <?php if(!$teamMembers):?><div class="team-empty"><h3><?=$teamSearch!==''?'No matching team members':'No team members assigned yet'?></h3><p><?=$teamSearch!==''?'Try another name or employee ID.':'Ask HR to set you as Reporting Manager in each team member’s profile.'?></p></div>
 <?php else:?>
 <div class="team-table" tabindex="0" role="region" aria-label="<?=$page==='team_people'?'Team people':'Team current attendance'?>"><table><thead><tr><th scope="col">Employee</th><?php if($page==='team_people'):?><th scope="col">Department</th><th scope="col">Designation</th><th scope="col">Employment status</th><?php else:?><th scope="col">Current status</th><th scope="col">Shift</th><th scope="col">Latest punch</th><th scope="col">Worked</th><th scope="col">Break</th><th scope="col">Overtime</th><?php endif;?><th scope="col">Records</th></tr></thead><tbody>
 <?php foreach($page==='team_people'?$teamMembers:$teamLive as $member):?><tr><th scope="row"><?=h($member['name'])?><small><?=h($member['employee_code']?:'No employee ID')?></small></th><?php if($page==='team_people'):?><td><?=h($member['department']?:'—')?></td><td><?=h($member['designation']?:'—')?></td><td><span class="team-badge <?=$member['employment_status']==='Active'?'is-in':''?>"><?=h($member['employment_status'])?></span></td><?php else:?><td><span class="team-badge <?=$member['state']==='in'?'is-in':''?>"><?=h($member['label'])?></span></td><td><?=h($member['shift'])?></td><td><?=h($member['last_punch']?date('d M, h:i A',strtotime($member['last_punch'])):'—')?></td><td><?=h(team_duration($member['worked']))?></td><td><?=h(team_duration($member['break']))?></td><td><?=h(team_duration($member['overtime']))?></td><?php endif;?><td><a class="team-record-link" href="<?=h($teamLink('team_attendance',['employee_id'=>(int)$member['user_id'],'month'=>date('Y-m')]))?>">View month</a></td></tr><?php endforeach;?>
 </tbody></table></div><?php endif;?></section>
 <?php if($page==='team_attendance'):?><p class="team-note">Current attendance uses the same punch calculations as the employee dashboard. Refresh to load the latest times. A shift ending does not create a check-out.</p><?php endif;?>
 <?php else:?>
 <a class="team-back" href="?page=team_attendance">← Back to team attendance</a>
 <form method="get" class="panel team-filter"><input type="hidden" name="page" value="team_attendance"><input type="hidden" name="employee_id" value="<?=$teamMemberId?>"><label>Attendance month<input type="month" name="month" value="<?=h($teamMonth)?>" required></label><button class="primary">View month</button><a class="wide-button" href="<?=h($teamLink('team_attendance',['employee_id'=>$teamMemberId,'month'=>$teamMonth,'export'=>1]))?>">Download CSV</a></form>
 <section class="panel team-records"><div class="team-heading"><div><h3><?=h($teamSelected['name'])?></h3><p><?=h(date('F Y',strtotime($teamMonth.'-01')))?> · <?=h($teamSelected['employee_code']?:'')?> · <?=count($teamRecords)?> calendar days · <?=h(date_default_timezone_get())?></p></div><span class="team-badge">Read-only</span></div>
 <div class="team-table" tabindex="0" role="region" aria-label="Team member monthly attendance"><table><thead><tr><?php foreach($teamHeaders as $label):?><th scope="col"><?=h($label)?></th><?php endforeach;?></tr></thead><tbody><?php foreach($teamRecords as $record):$cells=team_attendance_cells($record);?><tr><?php foreach($cells as $i=>$cell):?><?php if($i===0):?><th scope="row"><?=h($cell)?></th><?php else:?><td><?=h($cell)?></td><?php endif;?><?php endforeach;?></tr><?php endforeach;if(!$teamRecords):?><tr><td colspan="8">No attendance records for this month.</td></tr><?php endif;?></tbody></table></div></section>
 <p class="team-note">Dates follow the shift start, including overnight shifts. Monthly hours are saved attendance totals; open check-ins show “Awaiting checkout”. Contact HR for corrections.</p>
